for (const lang of locales) {
  for (const category of ui[lang].commandsPage.categories) {
    category.cmds.push(...commandRows(category.id, lang));
  }
  ui[lang].commandsPage.categories.push(...integrationCategories(lang));
}
function useTranslations(lang) {
  return ui[lang];
}
function sortedReleases(lang) {
  return [...ui[lang].releases.items].sort((a, b) => {
    if (!a.iso && !b.iso) return 0;
    if (!a.iso) return 1;
    if (!b.iso) return -1;
    return b.iso.localeCompare(a.iso);
  });
}

export { CODE_GENERATOR_URL as C, catalogCommands as c, generated as g, localePath as l, sortedReleases as s, useTranslations as u };
